"""Create the public report and figure from immutable aggregate replication results."""
import json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
HERE=Path(__file__).resolve().parent;r=json.loads((HERE/'RESULTS.json').read_text());comparisons=sorted(r['comparisons'],key=lambda s:(s['cohort']!='internal',s['seed']))
fig,axes=plt.subplots(1,2,figsize=(12,5.2),gridspec_kw={'width_ratios':[1.5,1]});names=[]
for i,s in enumerate(comparisons):
 label=('PTB-XL'if s['cohort']=='internal'else'New external')+' / '+str(s['seed']);names.append(label);color='#3156db'if s['cohort']=='internal'else'#a83916';effect=s['candidate_minus_quality_with_class_effect']*100;ci=np.array(s['CI95'])*100 if s['CI95']else None
 axes[0].plot(effect,i,'o',color=color)
 if ci is not None:axes[0].plot(ci,[i,i],color=color,lw=2)
 ret=np.array(s['candidate_AF_retention'])*100;axes[1].plot([ret.min(),ret.max()],[i,i],color=color,lw=2);axes[1].plot(ret,np.full(len(ret),i),'o',color=color,ms=4)
for ax in axes:ax.set_yticks(range(len(names)),names if ax==axes[0]else[]);ax.invert_yaxis();ax.spines[['top','right']].set_visible(False);ax.grid(axis='x',alpha=.2)
axes[0].axvline(0,ls='--',c='#666');axes[0].set_xlabel('Quality without class − quality with class (pp)');axes[0].set_title('Balanced retained error: pointwise 95% intervals')
axes[1].axvline(80,ls='--',c='#666');axes[1].set_xlim(0,102);axes[1].set_xlabel('AF-positive records retained (%)');axes[1].set_title('Range across four noise conditions')
fig.suptitle('Replication followup at 90% matched overall coverage',fontsize=15)
fig.text(.5,.015,'Internal: reused 2,085 ECGs / 151 AF records, participant bootstrap. New external: 930 ECGs / 37 AF records, record bootstrap.\nOriginal seed 20261015 is a reference; fresh training seeds 20261031 and 20261101. All intervals are conditional and pointwise.',ha='center',fontsize=8)
fig.tight_layout(rect=[0,.10,1,.93]);fig.savefig(HERE/'replication_summary.svg',bbox_inches='tight');fig.savefig(HERE/'replication_summary.png',dpi=160,bbox_inches='tight');plt.close(fig)
lines=['# Quality-without-predicted-class replication followup','', '**Result: the complete locked replication requirement was not met.** The internal seed results are favorable, and all new comparisons retain at least80% of AF cases, but one external comparison has an interval crossing zero. The original primary experiment and manuscript remain unchanged.','', '[Project and explorer](https://ksricharan7.github.io/portfolio/ecg.html#replication) · [Locked plan](PLAN.json) · [Implementation clarification](AMENDMENT_01.json) · [Aggregate results](RESULTS.json) · [Automated audit](AUDIT.json)','', '## What was added','', '- Two fresh classifier training seeds, 20261031 and 20261101, using the original development recipe and roles. Both passed checkpoint/ranker gates before evaluation.', '- A fixed sample of1,000 external header paths selected without labels, excluding every original2,000 sampled header. Of these,930 were eligible, including37 AF-positive records.', '- All original primary methods plus the quality-without-class ablation, at80%,90%,95% matched coverage and the unchanged90% fold9 policy target.', '- Paired2,000-resample intervals: participant sampling internally; record sampling externally because reliable patient linkage is unavailable.', '', '## Results at90% matched coverage','', 'Difference is quality without predicted class minus the original quality ranker **including predicted class**, averaged over em24/12/6/0. Negative favors the ablation. Intervals are pointwise, conditional on fitted models and the assigned noise library.','', '| Evaluation | Seed | Difference (pp) | 95% interval (pp) | Minimum AF retention | Comparison rule |','| --- | --- | ---: | --- | ---: | --- |']
for s in comparisons:
 e=s['candidate_minus_quality_with_class_effect']*100;ci=s['CI95'];lines.append(f"| {'Reused internal test'if s['cohort']=='internal'else'New external sample'} | {s['seed']} | {e:+.2f} | [{ci[0]*100:+.2f}, {ci[1]*100:+.2f}] | {min(s['candidate_AF_retention'])*100:.2f}% | {'Met'if s['comparison_requirement_passed']else'Not met'} |")
lines+=['','The original-seed internal result is shown for context and is not counted as new replication. Four of the five required new comparisons met the combined interval/retention rule. The external result for seed20261101 was −1.03pp with95% CI[−4.43,+1.87]pp; it cannot establish improvement for that model. All five new comparisons met the80% AF-retention criterion.','','![Replication effects and AF retention](replication_summary.svg)','','## Compare with simpler choices','','These are mean **balanced** errors across the four primary noisy conditions. Filtering methods use90% matched coverage; the unfiltered classifier retains every record. These point estimates are descriptive and are not new superiority tests.','','| Evaluation | Seed | Without-class error | Unfiltered error | Raw-confidence error | Minimum raw-confidence AF retention |','| --- | --- | ---: | ---: | ---: | ---: |']
for s in comparisons:
 m=s['method_summaries'];lines.append(f"| {'Internal'if s['cohort']=='internal'else'New external'} | {s['seed']} | {m['quality_no_class']['mean_balanced_retained_error']*100:.2f}% | {m['unfiltered']['mean_balanced_retained_error']*100:.2f}% | {m['raw_confidence']['mean_balanced_retained_error']*100:.2f}% | {min(m['raw_confidence']['AF_retention'])*100:.2f}% |")
lines+=['','The large internal gain is relative to a quality-plus-predicted-class ranker with50% balanced error. It is not a35–40pp gain over the unfiltered classifier. The tables retain all comparators and policies rather than selecting the best-looking method or seed.','','## Acquisition and implementation clarification','','The sampled provider headers had46 age exclusions,23 exclusions without an eligible rhythm code, and one header with an invalid date that the locked WFDB decoder could not parse. That malformed-header exclusion was committed before prediction evaluation. No sampled record was replaced and no raw header was repaired. All selected sources were checked against publisher hashes. There were no exact waveform duplicates within the new sample or matches with the earlier external or PTB-XL cohorts. This does not establish patient-identity disjointness.','','## Interpretation limits','','This is a locked followup of a posthoc finding, not a new confirmatory primary study or independent human replication. The internal test participants and NSTDB artifact source are reused. The new external records come from a previously studied dataset; the37 AF-positive records and lack of patient linkage limit precision and independence claims. The all-comparisons requirement failed, so the ablation is not promoted as a generally validated improvement or clinical tool. The original primary failure remains.','','The original34,791-file scientific freeze was verified unchanged. The new results are an addendum; the manuscript PDFs and original explorer result controls still describe the original benchmark.','','## Files and reproduction scope','','`matched_metrics.csv` contains480 aggregate rows; `fixed_policy_metrics.csv` contains150. `RESULTS.json` includes all six model/cohort comparisons, with the original internal seed marked as context. `AUDIT.json` records independent scalar metric checks and explicit bootstrap expansion checks. No source signals, clinical headers, individual predictions or participant identifiers are published.','','The two new CNNs, JSON rankers, policies and development locks are under`models/<seed>/`; the original candidate ranker is under`models/20261015/`. Fresh data-dependent fitting/evaluation scripts accept the path to the complete original working package because development caches, acquisition manifests and source datasets are omitted from the public repository. They are auditable research-source entry points, not an advertised turnkey raw-data training workflow. The original public fixed-model replay and dependency-free evidence checks remain documented in the top-level reproduction guide.','','To reconstruct the external selection, obtain ecg-arrhythmia1.0.0`SHA256SUMS.txt` directly from PhysioNet, then run:','','```bash','python extensions/quality-replication/make_selection.py /path/to/ecg-arrhythmia/SHA256SUMS.txt','python extensions/quality-replication/acquire_external.py /path/to/complete-working-package','python extensions/quality-replication/fit_fresh_seeds.py /path/to/complete-working-package','python extensions/quality-replication/evaluate_replication.py /path/to/complete-working-package','python extensions/quality-replication/audit_replication.py /path/to/complete-working-package','```','','Keep all generated`PRIVATE_*` files local. Existing source data and intermediate arrays are required; do not upload them to GitHub. The selection script reconstructs and excludes the original2000-header sample using its fixed20261019 seed, without reading header labels.','']
(HERE/'README.md').write_text('\n'.join(lines))
print('Created aggregate report and figure.')
